import java.util.List;

/**
 * 
 * @author Lukas
 *
 */
public class ElectionCheckParameter {
    private final List<Integer> numberVoters;
    private final List<Integer> numberCandidates;
    private final List<Integer> numberSeats;
    private final TimeOut timeOut;
    private final Integer processes;
    private final String argument;

    /**
     * 
     * @param numberVoters the list that specifies the range of voters
     * @param numberCandidates the list that specifies the range of candidates
     * @param numberSeats the list that specifies the range of seats
     * @param timeOut the timeout that specifies how long the checker should run
     * @param processes max number of processes of the checker
     * @param argument the arguments given by the user
     */
    public ElectionCheckParameter(List<Integer> numberVoters, List<Integer> numberCandidates, 
            List<Integer> numberSeats, TimeOut timeOut, Integer processes, String argument) {
        this.numberVoters = numberVoters;
        this.numberCandidates = numberCandidates;
        this.numberSeats = numberSeats;
        this.timeOut = timeOut;
        this.processes = processes;
        this.argument = argument;
    }

    /**
     * 
     * @return the list that specifies the range of voters
     */
    public List<Integer> getNumberVoters() {
        return numberVoters;
    }

    /**
     * 
     * @return the list that specifies the range of candidates
     */
    public List<Integer> getNumberCandidates() {
        return numberCandidates;
    }

    /**
     * 
     * @return the list that specifies the range of seats
     */
    public List<Integer> getNumberSeats() {
        return numberSeats;
    }

    /**
     * 
     * @return the timeout that specifies how long the checker should run
     */
    public TimeOut getTimeout() {
        return timeOut;
    }

    /**
     *
     * @return the amount of processes the user wishes to run at the same time
     */
    public Integer getProcesses() {
        return processes;
    }

    /**
     * 
     * @return the String that defines the advanced options 
     */
    public String getArgument() {
        return argument;
    }
}

