package com.dottydingo.hyperion.core.persistence;


/**
 * Specifies filters that can optionally limit access to data at the object level.
 */
public interface PersistenceFilter<P>
{
    /**
     * Return an optional filter that will be executed when processing a query request. This permits
     * data to be limited based off of permissions or call context.
     * @param persistenceContext The context
     * @return A query builder to add criteria to the query, null if no filter should be executed
     */
    PersistentQueryBuilder getFilterQueryBuilder(PersistenceContext persistenceContext);

    /**
     * Used to ascertain if a specific persistent item can be retrieved by ID
     * @param persistentObject The object
     * @param persistenceContext The context
     * @return true if the item should be accessible to the caller, false otherwise. If false
     * is returned then this item will be excluded from the response
     */
    boolean isVisible(P persistentObject, PersistenceContext persistenceContext);

    /**
     * Used to ascertain if the specified persistent object can be updated. This permits update limitations
     * to be added at the object level.
     * @param persistentObject The object to update
     * @param persistenceContext The context
     * @return True if the item can be generated, false otherwise.
     */
    boolean canUpdate(P persistentObject, PersistenceContext persistenceContext);

    /**
     * Used to ascertain if the specified persistent object can be removed. This permits remove limitations
     * to be added at the object level.
     * @param persistentObject The object to remove
     * @param persistenceContext The context
     * @return True if the item can be removed, false otherwise.
     */
    boolean canDelete(P persistentObject, PersistenceContext persistenceContext);
}

