public abstract class Duck {
    /**
     * объявляем две ссылочные переменные с типами интерфейсов поведения.
     * переменные наследуются всеми подклассами Duck (в том же пакете)
     * а не с типом конкретного класса реализации.
     * Каждый объект на стадии выполнения присваивается  этим переменным полиморфные значения,
     * соответствующие конкретному типу поведения (FlyWithWings,Squeak и т.д.)
     */
    FlyBehavior flyBehavior;// каждый  объект Duck содержит ссылку на реализацию интерфейса FlyBehavior.
    QuackBehavior quackBehavior;// каждый  объект Duck содержит ссылку на реализацию интерфейса QuackBehavior.

    public Duck(){
    }
    public abstract void display();

    public void performFly() { // делегирование операции классам поведения. этот метод заменяют fly().
        flyBehavior.fly();
    }
    public void performQuack() { // объект Duck делегирует поведения объекту, на который ссылается quackBehavior.
        quackBehavior.quack();
    }

    /**
     * добавим два новых метода
     * предположим мы хотим, чтобы тип поведения задавался set-методом подкласса (вместо создания экземпляра в конструкторе)
     * вызывая эти методы в любой момент, мы можем изменить поведение утки "на лету"
     * @param fb
     */
    public void setFlyBehavior(FlyBehavior fb) {
        flyBehavior = fb;
    }
    public void setQuackBehavior(QuackBehavior qb) {
        quackBehavior = qb;
    }

    public void swim() {
         System.out.println("Все утки плавают, даже манекены!");
    }
}

