package seedu.address.journalfeature.model;

import java.util.Arrays;

import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import seedu.address.journalfeature.model.journalEntry.JournalEntry;

/**
 *
 */

public class JournalEntryList {

    private final ObservableList<JournalEntry> entries = FXCollections.observableArrayList();
    private final ObservableList<JournalEntry> internalUnmodifiableList =
            FXCollections.unmodifiableObservableList(entries);

    /**
     * Add a new journal entry
     * @param entry
     * @return JournalEntry
     */
    public JournalEntry addJournalEntry(JournalEntry entry) {
        entries.add(entry);
        return entry;
    }

    /**
     * Delete the indicated journal entry
     * @param input
     * @return JournalEntry
     */
    public JournalEntry deleteJournalEntry(JournalEntry input) {
        if (entries.remove(input)) {
            return input.copy();
        }
        assert input != null;
        System.out.println("Entry should not be null and should exist in the list");
        return null;
    }

    /**
     * Set the indicated journal as private
     * @param output
     */
    public void setJournalEntryPrivate(JournalEntry output) {
        int change = entries.indexOf(output);
        JournalEntry input = entries.get(change);
        input.setPrivate();
        entries.set(change, input);
    }

    /**
     * Unprivate the indicated journal
     * @param output
     */
    public void setJournalEntryUnPrivate(JournalEntry output) {
        int change = entries.indexOf(output);
        JournalEntry input = entries.get(change);
        input.unPrivate();
        entries.set(change, input);
    }

    /**
     * Get the size of the journal list
     * @return int
     */

    public int getSize() {
        return entries.size();
    }

    /**
     * Check if the Journal List is empty
     * @return boolean
     */

    public boolean isEmpty() {
        if (entries.size() == 0) {
            return true;
        } else {
            return false;
        }
    }

    /**
     * Get all entries as a string
     * @return String
     */

    public String getEntriesAsString() {
        StringBuilder curr = new StringBuilder();
        int i = 0;
        for (JournalEntry temp : entries) {
            curr.append("Journal Entry: " + i + "\n");
            curr.append(temp.toString());
            curr.append("\n");
        }
        return curr.toString();
    }

    /**
     * In case of a corrupted/empty file, load sample data into JournalBook
     */

    public void loadData(JournalEntry[] myEntries) {
        Arrays.stream(myEntries).forEach(x -> addJournalEntry(x));
    }

    /**
     * Returns the backing list as an unmodifiable {@code ObservableList}.
     */
    public ObservableList<JournalEntry> asUnmodifiableObservableList() {
        return internalUnmodifiableList;
    }

    public boolean contains(JournalEntry someEntry) {
        return entries.contains(someEntry);
    }

