import java.io.Serializable;  
import java.util.List;  
import java.util.Set;  

/* One ultimate piece of information that's essential to get the algorithm  
     * operating is the capability to find and navigate strange alternating cycles in  
     * the alternating forest.  Once we've discovered such a cycle, we need to  
     * compress it down to a single node, find an alternating path in the  
     * compressed graph, then enlarge the path back into an alternating path in  
     * the original graph.  To perform this, we need to be capable of answering the  
     * following inquiries efficiently:  
     *  
     * 1. What nodes are in the cycle (blossom)?  
     * 2. Beginning at the root of the blossom, what sequence do the edges go in?  
     * 3. What node is utilized to denote the cycle in the compressed graph?  
     *  
     * This information is encoded in this utility struct.  
 */  
public class Blossom implements Serializable {  

    public final Node root;// The root of the blossom; also the representative  
    public final List<Node> cycle;// The nodes, listed in sequence around the cycle  
    public final Set<Node> nodes; // The nodes, stored in a set for effective lookup  

    /**  
     * Given information about the blossom, creates a new Blossom holding  
     * this information.  
     *  
     * @param root The root node of the blossom.  
     * @param cycle The nodes of the cycle listed in the sequence in which they  
     * occur in the blossom.  
     * @param nodes The nodes in the cycle, stored as a set.  
     */  
    public Blossom(Node root, List<Node> cycle, Set<Node> nodes) {  
        this.root = root;  
        this.cycle = cycle;  
        this.nodes = nodes;  
    }  

}

