import androidx.annotation.NonNull;

import com.otaliastudios.gif.transcode.Transcoder;

import java.nio.ByteBuffer;

/**
 * A DataCollector is an abstract representation of an encoded data aggregator.
 * Currently the only implementation is {@link DefaultDataCollector} which aggregates
 * data into a {@link java.io.File} using {@link android.media.MediaMuxer}.
 *
 * However there might be additional implementations in the future, for instance to stream data
 * to a server.
 */
public interface DataCollector {

    /**
     * Called before commencing to set the orientation metadata.
     * @param orientation 0, 90, 180 or 270
     */
    void setOrientation(int orientation);

    /**
     * Called by {@link Transcoder}s when they have an output format.
     * This is not the output format selected by the library user but rather the
     * output format established by {@link MediaCodec}, which contains further information,
     * and should be examined to know what kind of data we're aggregating.
     *
     * @param format the track format
     */
    void setFormat(@NonNull MediaFormat format);

    /**
     * Called by {@link Transcoder}s to write data into this collector.
     *
     * @param byteBuffer the data
     * @param bufferInfo the metadata
     */
    void write(@NonNull ByteBuffer byteBuffer,
               @NonNull MediaCodec.BufferInfo bufferInfo);

    /**
     * Called when transcoders have ceased writing.
     */
    void stop();

