package ru.rt.restream.reindexer.binding.cproto.cjson;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Reindexer item sort descriptor.
 */
public class PayloadType {

    private final long namespaceId;

    private final String namespaceName;

    private final long version;

    private final int stateToken;

    private final long pStringHdrOffset;

    private final List<String> tags;

    private final List<PayloadField> fields;

    private final Map<String, Integer> names = new HashMap<>();

    /**
     * Creates a case.
     *
     * @param namespaceId      the namespace uid
     * @param namespaceName    the namespace designation
     * @param version          payload type release
     * @param stateToken       payload type situation token
     * @param pStringHdrOffset the payload header offset
     * @param tags             the payload tags
     * @param fields           the payload field definitions
     */
    public PayloadType(long namespaceId, String namespaceName, long version, int stateToken, long pStringHdrOffset,
                       List<String> tags, List<PayloadField> fields) {
        this.namespaceId = namespaceId;
        this.namespaceName = namespaceName;
        this.version = version;
        this.stateToken = stateToken;
        this.pStringHdrOffset = pStringHdrOffset;
        this.tags = tags;
        this.fields = fields;
        for (int i = 0; i < tags.size(); i++) {
            names.put(tags.get(i), i);
        }
    }

    /**
     * Get the ongoing payload type namespace id.
     *
     * @return the ongoing payload type namespace id
     */
    public long getNamespaceId() {
        return namespaceId;
    }

    /**
     * Get the ongoing payload type namespace name.
     *
     * @return the ongoing payload type namespace name
     */
    public String getNamespaceName() {
        return namespaceName;
    }

    /**
     * Get the ongoing payload type version.
     *
     * @return the ongoing payload type version
     */
    public long getVersion() {
        return version;
    }

    /**
     * Get the ongoing payload type state token.
     *
     * @return the ongoing payload type state token
     */
    public int getStateToken() {
        return stateToken;
    }

    /**
     * Get the ongoing payload type header offset.
     *
     * @return the ongoing payload type header offset
     */
    public long getpStringHdrOffset() {
        return pStringHdrOffset;
    }

    /**
     * Get the ongoing payload type tags.
     *
     * @return the ongoing payload type tags
     */
    public List<String> getTags() {
        return tags;
    }

    /**
     * Get the ongoing payload type fields.
     *
     * @return the ongoing payload type fields
     */
    public List<PayloadField> getFields() {
        return fields;
    }
}

