package io.nosqlbench.engine.api.scoping;

import java.util.function.Supplier;

/**
 * Assistant class to consolidate the concepts of scoping items over different
 * NB layers of execution.
 */
public enum ScopedSupplier {

    /**
     * Once a provider is instantiated for singleton scope, it should provide only one instance of
     * the provided element for that instance. Multiple instances (separately constructed)
     * of the provider can each provide their own distinct provided instance.
     */
    singleton,
    /**
     * Once a provider is instantiated for thread scope, it should provide a unique instance of
     * the provided element for each thread, according to the inner provider's semantics.
     */
    thread,
    /**
     * When a provider is instantiated for caller scope, each time the provider is accessed,
     * it returns a new instance according to the inner provider's semantics.
     */
    caller;

    public <T> Supplier<T> supplier(Supplier<T> supplier) {

        switch (this) {
            case singleton:
                T got = supplier.get();
                return () -> got;
            case thread:
                ThreadLocal<T> tlsupplier = ThreadLocal.withInitial(supplier);
                return tlsupplier::get;
            case caller:
                return supplier;
            default:
                throw new RuntimeException("Unknown scope type:" + this);
        }
    }

}

