public class CollectionUtility {

    /**
     * Verify two collection has any matched item
     * @param collectionLeft the initial collection
     * @param collectionRight the following collection
     * @return located or not
     */
    public static boolean hasAny(Collection<?> collectionLeft, Collection<?> collectionRight) {
        for (Object o : collectionLeft) {
            for (Object i : collectionRight) {
                if (o.equals(i)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Create a list of item
     * @param items elements to include
     * @param <T> category of element
     * @return a ArrayList of given elements
     */
    public static <T> List<T> listOf(T... items) {
        List<T> list = new ArrayList<T>(items.length);
        Collections.addAll(list, items);
        return list;
    }

}

