 */
public class CollectionService {

    /**
     * Determine two collection has any identical item
     * @param collectionLeft the first collection
     * @param collectionRight the next collection
     * @return discovered or not
     */
    public static boolean containsAny(Collection<?> collectionLeft, Collection<?> collectionRight) {
        for (Object o : collectionLeft) {
            for (Object i : collectionRight) {
                if (o.equals(i)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Compile a list of item
     * @param items elements to contribute
     * @param <T> type of element
     * @return a ArrayList of supplied elements
     */
    public static <T> List<T> listOf(T... items) {
        List<T> list = new ArrayList<T>(items.length);
        Collections.addAll(list, items);
        return list;
    }

}

