public class SearchCommandParser implements ParserInterface<SearchCommand> {

    /**
     * Parse user input and return SearchCommand.
     * @param userInputStr String entered by user.
     * @return <code>SearchCommand</code> Command object encapsulating the query keywords
     * @throws ApplicationException If the userInput cannot be interpreted
