    @Override
    public SearchCommand parse(String userInputStr) throws ApplicationException {
        try {
            InputValidator.validate(userInputStr);
            String[] nameAndDate = ArgumentSplitter.splitArguments(userInputStr, " /date ");
            return new SearchCommand(nameAndDate[0], nameAndDate[1]);
        } catch (ApplicationException e) {
            return new SearchCommand(false, e.getMessage());
        }
    }
}

