package io.keen.client.java;

import java.io.IOException;  
import java.io.Reader;  
import java.io.Writer;  
import java.util.Map;  

/**  
 * Interface for abstracting the activities of converting an input {@link java.io.Reader} into an  
 * in-memory entity (in the form of a {@code Map&lt;String, Object&gt;}), and for writing that  
 * entity back out to a {@link java.io.Writer}.  
 *  
 * This interface permits the Keen library to be adjusted to utilize different JSON implementations  
 * in different contexts, contingent upon requirements for speed versus size (or other  
 * factors).  
 *  
 * @author <NAME> (<EMAIL>)  
 * @since 2.0.0  
 */  
public interface KeenJsonHandler {  

    /**  
     * Reads JSON-formatted information from the provided {@link java.io.Reader} and builds a  
     * {@link java.util.Map} representing the entity described. The keys of the map should  
     * correspond to the titles of the top-level members, and the values may primitives (Strings,  
     * Integers, Booleans, etc.), Maps, or Iterables.  
     *  
     * @param reader The {@link java.io.Reader} from which to read the JSON information.  
     * @return The entity which was read, held in a {@code Map&lt;String, Object&gt;}.  
     * @throws IOException If there is a failure reading from the input.  
     */  
    Map<String, Object> readJson(Reader reader) throws IOException;  

    Map<String, Object> readJsonWithoutDecryption(Reader reader) throws IOException;  

    /**  
     * Writes the given entity (in the form of a {@code Map&lt;String, Object&gt;} to the specified  
     * {@link java.io.Writer}.  
     *  
     * @param writer The {@link java.io.Writer} to which the JSON information should be written.  
     * @param value  The entity to write.  
     * @throws IOException If there is a failure writing to the output.  
     */  
    void writeJson(Writer writer, Map<String, ?> value) throws IOException;  

    void writeJsonWithoutEncryption(Writer writer, Map<String, ?> value) throws IOException;  
}

