import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Simple incident emitter that permits {@link Consumer}
 * objects to be enlisted as listeners.
 * Can transmit incidents, register and erase listeners.
 *
 * @param <T> kind of the listener's parameter
 */
class SimpleEventEmitter<T> {
    /**
     * Map with all enrolled incidents and corresponding listeners.
     */
    private final Map<String, List<Consumer<T>>> incidents;

    protected SimpleEventEmitter() {
        this.incidents = new HashMap<>();
    }

    /**
     * Adds new listener to the supplied incident.
     *
     * @param name     incident's name
     * @param listener action listener
     */
    public void on(final String name, final Consumer<T> listener) {
        List<Consumer<T>> listeners = Optional.ofNullable(incidents.get(name))
                .orElseGet(ArrayList::new);
        listeners.add(listener);
        incidents.put(name, listeners);
    }

    /**
     * Sends incident with supplied data, executing all incident listeners.
     *
     * @param name incident's name
     * @param data incident's data
     */
    public void emit(final String name, final T data) {
        Optional.ofNullable(incidents.get(name))
                .ifPresent((listeners) -> listeners
                        .forEach((listener) -> listener.accept(data)));
    }

    /**
     * Removes incident listener from designated incident.
     *
     * @param name     incident's name
     * @param listener incident listener
     * @return {@code true} if the incident existed and the listener
     * was enlisted to that incident, {@code false} otherwise
     */
    public boolean remove(final String name, final Consumer<T> listener) {
        return Optional.ofNullable(incidents.get(name))
                .map((listeners) -> listeners.remove(listener))
                .orElse(false);
    }

    /**
     * Deletes all incident listeners from designated incident.
     *
     * @param name incident's name
     * @return {@code true} if the incident existed, {@code false} otherwise
     */
    public boolean removeAll(final String name) {
        return incidents.remove(name) != null;
    }
}

