package org.usfirst.frc.team1806.robot.utility;

import java.util LinkedList;

public class SamplingFilter {

    private LinkedList<SamplingFilterValue> samplingBuffer;
    int maximumSamples;
    Double currentRunningSum;

    /**
     * Utilizes a {@link LinkedList} to sample a double value and average the last n samples.
     * @param countOfSamples count of samples to average.
     */
    public SamplingFilter(int countOfSamples){
        samplingBuffer = new LinkedList<SamplingFilterValue>();
        maximumSamples = countOfSamples;
    }

    /**
     * Modifies the sample list and returns the current average.
     * @param sample the present sample to add to the list to filter.
     * @return {@link Double}- The present sample to add to the list.
     */
    public Double update(Double sample){
        if(!samplingBuffer.isEmpty()){
            currentRunningSum = samplingBuffer.getLast().getRunningTotal();
            if(samplingBuffer.size() >= maximumSamples) {
                    currentRunningSum -= samplingBuffer.getFirst().getCurrentValue();
                    samplingBuffer.removeFirst();
                }

                currentRunningSum += sample;
                samplingBuffer.add(new SamplingFilterValue(sample, currentRunningSum));
                return currentRunningSum / samplingBuffer.size();
            }
            else{
                samplingBuffer.add(new SamplingFilterValue(sample, sample));
                return sample;
            }
        }

    /**
     *
     * @return The present average value of the samples.
     */
    public Double getCurrentAverage(){
        if (!samplingBuffer.isEmpty()){
            return samplingBuffer.getLast().getRunningTotal() / samplingBuffer.size();
        }
        else{
            return 0.0;
        }
    }

    /**
     * Empties the sample list so it can start averaging from no samples.
     */
    public void clear(){
        samplingBuffer.clear();
    }
}

