package edu.mit.simile.butterfly;

import java.net.URL;

public class Zone {

    private String title;
    private String format;
    private String server;
    private String route;

    private String prefix;
    private String complete;

    public Zone(String title, String zoneRoute) {
        this.title = title;
        int index = zoneRoute.indexOf("://");
        if (index > 0) {
            try {
                URL url = new URL(zoneRoute);
                format = url.getProtocol();
                server = url.getHost();
                route = url.getPath();
            } catch (Exception e) {
                throw new RuntimeException("Could not parse the zone route '" + zoneRoute + "', make sure it's a valid HTTP URL or an absolute path.", e);
            }
        } else {
            route = zoneRoute;
        }

        if (!route.startsWith("/")) route = "/" + route;
        if (route.endsWith("/")) route = route.substring(0,route.length() - 1);

        StringBuffer b = new StringBuffer();
        if (format != null) {
            b.append(format);
            b.append("://");
        }
        if (server != null) {
            b.append(server);
        }
        prefix = b.toString();
        b.append(route);
        complete = b.toString();
    }

    public String getPrefix() {
        return this.prefix;
    }

    public String getPath() {
        return this.route;
    }

    public String getName() {
        return this.title;
    }

    public String toString() {
        return this.complete;
    }

}

