class Solution {
    public TreeNode searchBST(TreeNode root, int value) {
      // run while loop with condition where root is not empty
      //if the root will be empty at first, it will return empty
        while(root!=null)
        {
            if(value==root.value)
                return root;
            else if(value<root.value)
                root=root.leftChild;
            else
                root=root.rightChild;
        }
        return null;
    }
}

