import java.util.Date;

/**
 * Super class that allows recording of objects' timestamps.
 *
 * @author https://github.com/JeffreyDeYoung
 */
public abstract class Timestamped
{

    private Date createdAt;
    private Date lastUpdatedAt;

    public Timestamped()
    {
        //default for now
        createdAt = new Date();
        lastUpdatedAt = new Date();
    }

    public Date getCreatedAt()
    {
        return (createdAt == null ? null : new Date(createdAt.getTime()));
    }

    public Date getLastUpdatedAt()
    {
        return (lastUpdatedAt == null ? null : new Date(lastUpdatedAt.getTime()));
    }

    public void setCreatedAt(Date date)
    {
        this.createdAt = (date == null ? new Date() : new Date(date.getTime()));
    }

    public void setLastUpdatedAt(Date date)
    {
        this.lastUpdatedAt = (date == null ? new Date() : new Date(date.getTime()));
    }
}

