package org.zstack.header.identity;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class IdentityCategory {
    private static Map<String, IdentityCategory> types = Collections.synchronizedMap(new HashMap<String, IdentityCategory>());
    private final String categoryName;

    public IdentityCategory(String categoryName) {
        this.categoryName = categoryName;
        types.put(categoryName, this);
    }

    public static boolean hasCategory(String category) {
        return types.keySet().contains(category);
    }

    public static IdentityCategory valueOf(String categoryName) {
        IdentityCategory category = types.get(categoryName);
        if (category == null) {
            throw new IllegalArgumentException("Identity category: " + categoryName + " was not registered by any HypervisorFactory");
        }
        return category;
    }

    @Override
    public String toString() {
        return categoryName;
    }

    @Override
    public boolean equals(Object t) {
        if (t == null || !(t instanceof IdentityCategory)) {
            return false;
        }

        IdentityCategory category = (IdentityCategory) t;
        return category.toString().equals(categoryName);
    }

    @Override
    public int hashCode() {
        return categoryName.hashCode();
    }
}

