        this.beat -= beat;
    }

    public boolean hasElapsed(int beat) {
        return this.beat >= beat;
    }

    public boolean isWithin(int min, int max) {
        return min <= beat && beat <= max;
    }

    public int getBeat() {
        return beat;
    }

    public void setBeat(int beat) {
        this.beat = beat;
    }
    public void reset() {
        beat = beginning;
    }

