package io.github.marioluan.datastructures;

/**
 * Implementation of a vertex data structure with a link to its subsequent and prior
 * vertices.
 * 
 * @author marioluan
 * @param <T>
 *            the class type of the information being managed
 */
public class Vertex<T extends Comparable<T>> implements Comparable<Vertex<T>> {

    /**
     * The value of the vertex.
     */
    public T data;

    /**
     * A link to the subsequent vertex.
     */
    public Vertex<T> next;

    /**
     * A link to the prior vertex.
     */
    public Vertex<T> prev;

    /**
     * Construct a new vertex with the specified data.
     * 
     * @param data
     */
    public Vertex(T data) {
        this.data = data;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public int compareTo(Vertex<T> that) {
        return this.data.compareTo(that.data);
    }

    /**
     * Checks whether there is a link to subsequent vertex.
     * 
     * @return whether the next field is not null
     */
    public boolean hasNext() {
        return this.next != null;
    }

    /**
     * Checks whether there is a link to prior vertex.
     * 
     * @return whether the prev field is not null
     */
    public boolean hasPrev() {
        return this.prev != null;
    }

}

