import java.io.Serializable;  
import java.util List;  

/**  
 * This class permits access to the ID and the modification of entities of a specific kind.  
 *  
 * @author rwitzel  
 * @param <T>  
 *            the kind of the handled entities  
 * @param <ID>  
 *            the kind of the ID of the handled entities  
 */  
public interface EntityInformation<T, ID extends Serializable> {  

    /**  
     * Converts the specified ID to a CouchDB identifier.  
     *  
     * @param id the ID of the entity  
     * @return Returns the altered identifier.  
     */  
    String toCouchId(ID id);  

    List<String> toCouchIds(Iterable<ID> iter);  

    /**  
     * @param entity the entity  
     * @return Returns the CouchDb identifier of the entity.  
     */  
    String getCouchId(T entity);  

    /**  
     * Assigns the identifier of the entity, i.e. alters the specified CouchDb identifier if necessary.  
     *  
     * @param entity the entity  
     * @param couchId the CouchID for the entity  
     */  
    void setId(T entity, String couchId);  

    /**  
     * @param entity the entity  
     * @return Returns the revision of the specified entity.  
     */  
    String getRev(T entity);  

    /**  
     * Assigns the revision in the specified entity.  
     *  
     * @param entity the entity  
     * @param rev the new revision for the entity  
     */  
    void setRev(T entity, String rev);  

    /**  
     * @param entity the entity  
     * @return Returns true if the specified entity is new, i.e. it does not have a revision.  
     */  
    boolean isNew(T entity);  
}

