        }
        return null;
    }

    @Override
    public void addList(IPlaylist list) {
        playlists.add(list);
    }

    @Override
    public void removeList(String name) {
        playlists.remove(getList(name));
    }

    @Override
    public void removeList(IPlaylist list) {
        playlists.remove(list);
    }
}

