 * This class envelops an output stream, storing a reference to its originating socket. When the stream
 * is closed, it will also shut the socket immediately afterward. This class is helpful for
 * situations where you are managing a stream originating from a socket, but do not have a
 * reference to the socket, and want to ensure it shuts when the stream closes.
 * 
 * @see SocketInputStream
 ***/

public class SocketOutputStream extends FilterOutputStream {
	private final Socket __socket;

	/***
	 * Creates a SocketOutputStream instance enveloping an output stream and storing a reference to a
	 * socket that should be shut on closing the stream.
	 * 
	 * @param socket The socket to shut on closing the stream.
	 * @param stream The input stream to envelop.
	 ***/
	public SocketOutputStream(Socket socket, OutputStream stream) {
		super(stream);
		__socket = socket;
	}

	/***
	 * Writes a number of bytes from a byte array to the stream beginning from a given offset. This
	 * method circumvents the equivalent method in FilterOutputStream because the FilterOutputStream
	 * implementation is very ineffective.
	 * 
	 * @param buffer The byte array to write.
	 * @param offset The offset into the array at which to start duplicating data.
	 * @param length The number of bytes to write.
	 * @exception IOException If an error happens while writing to the underlying stream.
	 ***/
	@Override
	public void write(byte buffer[], int offset, int length) throws IOException {
		out.write(buffer, offset, length);
	}

	/***
	 * Closes the stream and immediately afterward shuts the referenced socket.
	 * 
	 * @exception IOException If there is an error in shutting the stream or socket.
	 ***/
	@Override
	public void close() throws IOException {
		super.close();
		__socket.close();
	}

