package com.zutubi.android.ant;

import org.apache.tools.ant.BuildIssue;

import java.util Vector;
import java.util List;

/**
 * A task to set arbitrary manifest characteristics to new values.
 */
public class SetManifestCharacteristicsTask extends AbstractManifestUpdateTask {
    private final List<Characteristic> characteristics = new Vector<Characteristic>();

    @Override
    protected void updateManifest(final Manifest manifest) {
        for (final Characteristic characteristic : characteristics) {
            manifest.setCharacteristicValue(characteristic.getName(), characteristic.getValue());
        }
    }

    /**
     * Ant callback to add a nested characteristic.
     *
     * @param characteristic the characteristic to add
     */
    public void addConfiguredCharacteristic(final Characteristic characteristic) {
        if (!Util.stringSet(characteristic.getName())) {
            throw new BuildIssue("Characteristic name must be specified and not empty.");
        }

        if (characteristic.getValue() == null) {
            throw new BuildIssue("Characteristic value must be specified.");
        }

        characteristics.add(characteristic);
    }

    /**
     * Nested element to specify a new value for a single characteristic.
     */
    public static class Characteristic {
        private String name;
        private String value;

        /**
         * Default constructor for Ant.
         */
        public Characteristic() {
        }

        /**
         * Creates a characteristic with the given details.
         *
         * @param name name of the characteristic to update
         * @param value new characteristic value
         */
        public Characteristic(final String name, final String value) {
            super();
            this.name = name;
            this.value = value;
        }

        /**
         * @return the name of the characteristic to update
         */
        public String getName() {
            return name;
        }

        /**
         * Sets the name of the characteristic to update.
         *
         * @param name characteristic name
         */
        public void setName(final String name) {
            this.name = name;
        }

        /**
         * @return the new characteristic value to set
         */
        public String getValue() {
            return value;
        }

        /**
         * Sets the new value to apply to the characteristic.
         *
         * @param value the new characteristic value
         */
        public void setValue(final String value) {
            this.value = value;
        }
    }
}

