package grondag.mcmd.parser.separator;

import grondag.mcmd.node.Text;

/**
 * Custom separator processor for additional separators besides {@code _} and {@code *}.
 * <p>
 * Note that implementations of this need to be thread-safe, the same instance may be utilized by multiple parsers.
 */
public interface SeparatorProcessor {

    /**
     * @return the character that marks the beginning of a separated node, must not clash with any built-in special
     * characters
     */
    char getStartingCharacter();

    /**
     * @return the character that marks the the ending of a separated node, must not clash with any built-in special
     * characters. Note that for a symmetric separator such as "*", this is the same as the starting.
     */
    char getFinishingCharacter();

    /**
     * Minimum number of separator characters that are needed to activate this. Must be at least 1.
     */
    int getMinSize();

    /**
     * Determine how many (if any) of the separator characters should be used.
     * <p>
     * This allows implementations to decide how many characters to use based on the properties of the separator runs.
     * An implementation can also return 0 when it doesn't want to permit this particular combination of separator runs.
     *
     * @param opener the starting separator run
     * @param closer the finishing separator run
     * @return how many separators should be employed; must not be greater than length of either opener or closer
     */
    int getSeparatorUse(SeparatorRun opener, SeparatorRun closer);

    /**
     * Process the matched separators, e.g. by wrapping the nodes between opener and closer in a new node, or appending
     * a new node after the opener.
     * <p>
     * Note that removal of the separator from the separator nodes and unlinking them is done by the caller.
     *
     * @param opener the text node that contained the starting separator
     * @param closer the text node that contained the finishing separator
     * @param separatorUse the number of separators that were utilized
     */
    void process(Text opener, Text closer, int separatorUse);

}

