package io.codescan.sarif.model;

import java.util.List;  
import lombok.Data;  
import lombok.experimental.Accessors;

/**  
 * Depicts a singular run of an evaluation tool, and encompasses the relayed output of that run.  
 */  
@Data  
@Accessors(chain = true)  
public class Run {  

    /**  
     * Details about the tool or tool pipeline that produced the outcomes in this run. A run can only include  
     * outcomes generated by a singular tool or tool pipeline. A run can collect outcomes from multiple log records, as long  
     * as context surrounding the tool run (tool command-line parameters and the like) is identical for all collected files.  
     */  
    private Tool tool;  

    /**  
     * The collection of outcomes contained in an SARIF log. The outcomes array can be omitted when a run is solely exporting  
     * regulations metadata. It must be present (but may be vacant) if a log file signifies an actual scan.  
     */  
    private List<Result> results;  
}

