// Adapted from http://danifold.net/fastmerge.html  
public class UnionLink {  
    /*  
     * Lookup function for a union-link data structure.  
     *  
     * The function finds the root of idx by going iteratively through all  
     * ancestor elements until a root is found. An element i is a root if nodes[i]  
     * is zero. To make subsequent searches quicker, the entry for idx and all  
     * its ancestors is updated with the root element.  
     */  

    int[] ancestor;  
    int nextancestor;  

    public UnionLink(int size) {  
        ancestor = new int[size > 0 ? 2 * size - 1 : 0];  
        nextancestor = size;  
    }  

    int find(int idx) {  
        if (ancestor[idx] != 0) { // a → b  
            int p = idx;  
            idx = ancestor[idx];  
            if (ancestor[idx] != 0) { // a → b → c  
                do {  
                    idx = ancestor[idx];  
                } while (ancestor[idx] != 0);  
                do {  
                    int tmp = ancestor[p];  
                    ancestor[p] = idx;  
                    p = tmp;  
                } while (ancestor[p] != idx);  
            }  
        }  
        return idx;  
    }  

    void unite(int node1,  
               int node2) {  
        ancestor[node1] = ancestor[node2] = nextancestor++;  
    }  

}

