package org.sunflow.util;  

public final class IntList {  

    private int[] collection;  
    private int count;  

    public IntList() {  
        collection = new int[10];  
        count = 0;  
    }  

    public IntList(int sizeLimit) {  
        collection = new int[sizeLimit];  
        count = 0;  
    }  

    /**  
     * Append an integer to the end of the collection.  
     *  
     * @param i  
     */  
    public final void add(int i) {  
        if (count == collection.length) {  
            int[] previousCollection = collection;  
            collection = new int[(count * 3) / 2 + 1];  
            System.arraycopy(previousCollection, 0, collection, 0, count);  
        }  
        collection[count] = i;  
        count++;  
    }  

    /**  
     * Write a value to the indicated index. Assumes the collection is already big  
     * enough.  
     *  
     * @param index  
     * @param value  
     */  
    public final void set(int index, int value) {  
        collection[index] = value;  
    }  

    /**  
     * Read value from the collection.  
     *  
     * @param index index into the collection  
     * @return value at the indicated index  
     */  
    public final int get(int index) {  
        return collection[index];  
    }  

    /**  
     * Returns the number of elements added to the collection.  
     *  
     * @return current count of the collection  
     */  
    public final int getCount() {  
        return count;  
    }  

    /**  
     * Return a copy of the collection, trimmed to fit the count of its contents  
     * exactly.  
     *  
     * @return a new collection of exactly the right length  
     */  
    public final int[] trim() {  
        if (count < collection.length) {  
            int[] previousCollection = collection;  
            collection = new int[count];  
            System.arraycopy(previousCollection, 0, collection, 0, count);  
        }  
        return collection;  
    }  
}

