 * Popup primary class which holds all functionality for adding/removing a popup layout to/from a container.
 * @author horatiuf
 */

abstract class PopupBase {

    /**
     * Inflated view that will signify the popup.
     */
    ViewGroup panel;

    /**
     * Returns a boolean indicating if the dialog is apparent or not.
     * @return if true, layout is apparent
     */
    public boolean isVisible() {
        return panel != null && panel.getVisibility() == View.VISIBLE;
    }

