package com.nucleus.scene;

import java.util.ArrayList;

/**
 * Navigates the nodetree in a breadth first fashion.
 *
 */
public class BreadthFirstNodeIterator extends NodeIterator {

    ArrayList<Node> offspring;

    /**
     * Creates a new nodeiterator
     * 
     * @param start
     * @throws IllegalArgumentException If start is null
     */
    public BreadthFirstNodeIterator(Node start) {
        super(start);
    }

    @Override
    public boolean hasNext() {
        // TODO Auto-generated method stub
        return false;
    }

    @Override
    public Node next() {
        if (offspring == null) {
            offspring = start.getChildren();
        }
        return null;
    }

    /**
     * Returns the node and childnodes as breadth first list
     * 
     * @param start
     * @return
     */
    public ArrayList<Node> breadthFirstList(Node start) {
        return addNode(null, null, start);
    }

    private ArrayList<Node> addNode(ArrayList<Node> result, ArrayList<Node> offspring, Node node) {
        if (result == null) {
            result = new ArrayList<>();
        }
        if (offspring == null) {
            offspring = new ArrayList<>();
        }
        result.add(node);
        offspring.addAll(node.getChildren());
        addChildren(result, offspring, node);
        return result;
    }

    private void addChildren(ArrayList<Node> result, ArrayList<Node> parents, Node parent) {
        ArrayList<Node> offspring = new ArrayList<>();
        for (Node n : parents) {
            addNode(result, offspring, n);
        }
    }

}

