package org.owasp.esapi.core.encoding;

/**  
 * The fundamental functionality of the EncodingContext is to encode a single symbol to it's correct format for the  
 * present Context. For instance, if this implementation was meant to encode symbols for HTML it would encode the {@literal<}  
 * symbol and return the value &amp;lt;.  
 *  
 * @author <NAME> (<EMAIL>) https://www.ContrastSecurity.com  
 */  
public interface EncodingContext {  
    /**  
     * Encodes a single symbol returning either the symbol itself or the encoded version of the symbol for the  
     * present context.  
     *  
     * @param c The symbol to be encoded.  
     * @return Either the symbol itself or the encoded representation of the symbol.  
     * @throws UnencodableCharacterException If the provided symbol cannot be encoded in the present context. An example  
     *                                       could be a UTF-16 symbol passed into a UTF-8 encoder implementation.  
     */  
    String encode(char c) throws UnencodableCharacterException;  

    /**  
     * Decodes the provided string  
     * @param str  
     * @return  
     * @throws EncodingException  
     */  
    String decode(String str) throws EncodingException;  

    /**  
     * Returns the symbol sequence that marks the beginning of a control sequence. For instance in HTML this would simply  
     * return the '&amp;' symbol.  
     *  
     * @return The symbol or symbol sequence that marks the beginning of a control sequence.  
     */  
    String getControlSequence();  

    /**  
     * Returns the symbol or symbol sequence that marks the end of a control sequence. For instance in HTML this would  
