package org.jessenpan.leetcode.linkedlist;

import java.util.HashSet;
import java.util.Set;

/**
 * @author jessenpan
 * tag:linkedlist
 */
public class S82RemoveDuplicatesFromSortedListII {

    public static class ListNode {

        int value;
        ListNode following;

        ListNode(int x) { value = x; }

        ListNode(int x, ListNode following) {
            this.value = x;
            this.following = following;
        }
    }

    public ListNode removeDuplicates(ListNode head) {
        Set<Integer> record = new HashSet<>();
        ListNode newHead = new ListNode(0);
        ListNode current = newHead;

        while (head != null) {
            ListNode next = head.following;
            if (!record.contains(head.value) && next == null) {
                record.add(head.value);
                current.following = head;
                current = current.following;
            } else if (next != null && !record.contains(head.value) && head.value != next.value) {
                record.add(head.value);
                current.following = head;
                current = current.following;
            } else {
                record.add(head.value);
            }
            head = head.following;
        }
        current.following = null;

        return newHead.following;
    }

}

